const fs = require('fs');
const path = require('path');

let Font;
let parse;

const fontsDir = path.join(__dirname, '..', 'fonts');

function readFont(name) {
    return fs.readFileSync(path.join(fontsDir, name));
}

function toArrayBuffer(nodeBuffer) {
    return nodeBuffer.buffer.slice(
        nodeBuffer.byteOffset,
        nodeBuffer.byteOffset + nodeBuffer.byteLength
    );
}

function findTableEntry(buffer, tag) {
    const numTables = buffer.readUInt16BE(4);
    for (let i = 0; i < numTables; i += 1) {
        const entryOffset = 12 + i * 16;
        if (buffer.toString('latin1', entryOffset, entryOffset + 4) === tag) {
            return entryOffset;
        }
    }
    throw new Error(`Table ${tag} not found in fixture`);
}

function renameTable(buffer, oldTag, newTag) {
    const result = Buffer.from(buffer);
    const entryOffset = findTableEntry(result, oldTag);
    result.write(newTag, entryOffset, 4, 'latin1');
    return result;
}

function changeTableOffset(buffer, tag, offset) {
    const result = Buffer.from(buffer);
    const entryOffset = findTableEntry(result, tag);
    result.writeUInt32BE(offset, entryOffset + 8);
    return result;
}

function putTableAtEnd(buffer, oldTag, newTag, tableData) {
    const result = Buffer.from(buffer);
    const entryOffset = findTableEntry(result, oldTag);
    result.write(newTag, entryOffset, 4, 'latin1');
    result.writeUInt32BE(result.length, entryOffset + 8);
    result.writeUInt32BE(tableData.length, entryOffset + 12);
    return Buffer.concat([result, tableData]);
}

function makeMetaTable(text) {
    const payload = Buffer.from(text, 'utf8');
    const result = Buffer.alloc(28);
    result.writeUInt32BE(1, 0); // version
    result.writeUInt32BE(0, 4); // flags
    result.writeUInt32BE(28, 8); // offset to data maps
    result.writeUInt32BE(1, 12); // number of data maps
    result.write('TEST', 16, 4, 'latin1');
    result.writeUInt32BE(28, 20); // text offset relative to table start
    result.writeUInt32BE(payload.length, 24);
    return Buffer.concat([result, payload]);
}

