test('parses an ArrayBuffer TrueType font and populates its tables and glyphs', () => {
    const buffer = readFont('Roboto-Black.ttf');
    const font = parse(toArrayBuffer(buffer));

    expect(font).toBeInstanceOf(Font);
    expect(font.outlinesFormat).toBe('truetype');
    expect(font.unitsPerEm).toBe(2048);
    expect(font.ascender).toBe(1900);
    expect(font.descender).toBe(-500);
    expect(font.numGlyphs).toBe(1294);
    expect(font.numberOfHMetrics).toBe(1294);

    expect(font.tables.head.magicNumber).toBe(0x5F0F3CF5);
    expect(font.tables.head.unitsPerEm).toBe(2048);
    expect(font.tables.hhea.ascender).toBe(1900);
    expect(font.tables.hhea.descender).toBe(-500);
    expect(font.tables.maxp.numGlyphs).toBe(1294);
    expect(font.tables.os2).toBeDefined();
    expect(font.tables.post).toBeDefined();
    expect(font.tables.cmap).toBeDefined();
    expect(font.tables.gdef).toBeDefined();
    expect(font.tables.gpos).toBeDefined();
    expect(font.tables.gsub).toBeDefined();
    expect(font.tables.gasp.version).toBe(1);
    expect(font.tables.cvt).toHaveLength(45);
    expect(font.tables.fpgm).toHaveLength(444);
    expect(font.tables.prep).toHaveLength(312);

    expect(font.glyphs.length).toBe(1294);
    expect(font.encoding.charToGlyphIndex('A')).toBe(37);
    expect(font.glyphs.get(37).path.commands.length).toBeGreaterThan(0);
    expect(font.glyphs.get(37).advanceWidth).toBe(1395);
    expect(font.tables.name.windows.fontFamily.en).toBe('Roboto Black');
    expect(font.names).toBe(font.tables.name);
    expect(font.kerningPairs).toEqual({});
    expect(font.palettes.font).toBe(font);
});

test('accepts Node Buffers and Uint8Arrays as input', () => {
