    expect(cffWoff.numGlyphs).toBe(1147);
    expect(cffWoff.tables.cff).toBeDefined();
    expect(cffWoff.glyphs.length).toBe(1147);
    expect(cffWoff.glyphs.get(1).name).toBe('.notdef');

    const trueTypeWoff = parse(readFont('Vibur.woff'));
    expect(trueTypeWoff.outlinesFormat).toBe('truetype');
