function findTableEntry(buffer, tag) {
    const numTables = buffer.readUInt16BE(4);
    for (let i = 0; i < numTables; i += 1) {
        const entryOffset = 12 + i * 16;
        if (buffer.toString('latin1', entryOffset, entryOffset + 4) === tag) {
            return entryOffset;
        }
