export function makeIndex(objects, version = 1) {
    const count = objects.length;
    const countLength = version > 1 ? 4 : 2;
    const bytes = [];
    if (count === 0) {
        for (let i = 0; i < countLength; i += 1) bytes.push(0);
        return bytes;
    }
    const dataBytes = [];
    const offsets = [1];
    for (let i = 0; i < count; i += 1) {
        const obj = objects[i];
        for (let j = 0; j < obj.length; j += 1) dataBytes.push(obj[j] & 0xff);
        offsets.push(offsets[offsets.length - 1] + obj.length);
    }
    const maxOffset = offsets[count];
    let offSize = 1;
    while (maxOffset >= Math.pow(256, offSize)) offSize += 1;
    for (let i = countLength - 1; i >= 0; i -= 1) bytes.push((count >> (8 * i)) & 0xff);
    bytes.push(offSize);
    for (let i = 0; i < offsets.length; i += 1) {
