    return op >= 1200 ? [12, op - 1200] : [op];
}

export function dictEntry(operands, op) {
    const out = [];
    for (let i = 0; i < operands.length; i += 1) {
        const enc = dictNumber(operands[i]);
        for (let j = 0; j < enc.length; j += 1) out.push(enc[j]);
    }
    const opBytes = dictOp(op);
    for (let i = 0; i < opBytes.length; i += 1) out.push(opBytes[i]);
    return out;
}

export function buildCFF1(cfg) {
    const header = [1, 0, 4, 2];
    const nameIndex = makeIndex(cfg.names || [[65]], 1);
    const stringIndex = makeIndex(cfg.strings || [], 1);
    const gsubrsIndex = makeIndex(cfg.gsubrs || [], 1);
    const charsetBytes = cfg.charsetBytes || [];
    const charStringsIndex = makeIndex(cfg.charStrings || [[]], 1);
    const subrsIndex = cfg.subrs ? makeIndex(cfg.subrs, 1) : [];
