        const len = privateBytes.length;
        privateBytes = cfg.privateEntries(len);
        if (privateBytes.length !== len) throw new Error('unstable private dict length');
    }
    const placeholder = cfg.topDictEntries({charStrings: 0, private: 0, charset: 0, encoding: 0, fdArray: 0, fdSelect: 0});
    const topDictIndexLen = makeIndex([placeholder], 1).length;
    let offset = 4 + nameIndex.length + topDictIndexLen + stringIndex.length + gsubrsIndex.length;
    const offsets = {};
    offsets.charset = offset; offset += charsetBytes.length;
    offsets.charStrings = offset; offset += charStringsIndex.length;
    offsets.private = offset; offset += privateBytes.length;
    offset += subrsIndex.length;
    offsets.fdPrivate = offset;
    const fdPrivateBytes = cfg.fdPrivateBytes || [];
    offset += fdPrivateBytes.length;
    const fdArrayObjects = cfg.fdArrayObjects ? cfg.fdArrayObjects(offsets.fdPrivate) : [];
    const fdArrayIndex = makeIndex(fdArrayObjects, 1);
    offsets.fdArray = offset; offset += fdArrayIndex.length;
    const fdSelectBytes = cfg.fdSelectBytes || [];
    offsets.fdSelect = offset;
    const topDictBytes = cfg.topDictEntries(offsets);
    if (topDictBytes.length !== placeholder.length) throw new Error('unstable top dict length');
    const topDictIndex = makeIndex([topDictBytes], 1);
    const out = [...header, ...nameIndex, ...topDictIndex, ...stringIndex, ...gsubrsIndex, ...charsetBytes, ...charStringsIndex, ...privateBytes, ...subrsIndex, ...fdPrivateBytes, ...fdArrayIndex, ...fdSelectBytes];
    return new Uint8Array(out);
}

export function toDataView(bytes, prefixLength = 0) {
    const buf = new Uint8Array(prefixLength + bytes.length);
    buf.set(bytes, prefixLength);
    return new DataView(buf.buffer);
}
