/**
 * Unit tests for the `parseCFFTable` function exported as `cff.parse`
 * from `src/tables/cff.mjs`.
 *
 * Two kinds of fixtures are used:
 *  - a CFF1 table produced by the library's own `cff.make()`, to exercise realistic data;
 *  - hand assembled minimal CFF1/CFF2 binaries, to reach edge cases and error paths that
 *    the writer cannot produce.
 */

let cff;
let Glyph;
let Path;
let encodingModule;
let fs;
let pathModule;

beforeAll(async () => {
    cff = (await import('../../../src/tables/cff.mjs')).default;
    Glyph = (await import('../../../src/glyph.mjs')).default;
    Path = (await import('../../../src/path.mjs')).default;
    encodingModule = await import('../../../src/encoding.mjs');
    fs = await import('node:fs');
    pathModule = await import('node:path');
});

// ---------------------------------------------------------------------------
// Binary fixture helpers
// ---------------------------------------------------------------------------

/**
 * Encode a CFF INDEX. Version 1 uses a Card16 object count, version 2 a ULong.
 */
function makeIndex(objects, version = 1) {
    const count = objects.length;
    const countLength = version > 1 ? 4 : 2;
    const bytes = [];
    if (count === 0) {
        for (let i = 0; i < countLength; i += 1) {
            bytes.push(0);
        }
        return bytes;
    }
    const dataBytes = [];
    const offsets = [1];
    for (let i = 0; i < count; i += 1) {
        const obj = objects[i];
        for (let j = 0; j < obj.length; j += 1) {
            dataBytes.push(obj[j] & 0xff);
        }
        offsets.push(offsets[offsets.length - 1] + obj.length);
    }
    const maxOffset = offsets[count];
    let offSize = 1;
    while (maxOffset >= Math.pow(256, offSize)) {
        offSize += 1;
    }
    for (let i = countLength - 1; i >= 0; i -= 1) {
        bytes.push((count >> (8 * i)) & 0xff);
    }
    bytes.push(offSize);
    for (let i = 0; i < offsets.length; i += 1) {
        for (let j = offSize - 1; j >= 0; j -= 1) {
            bytes.push((offsets[i] >> (8 * j)) & 0xff);
        }
    }
    for (let i = 0; i < dataBytes.length; i += 1) {
        bytes.push(dataBytes[i]);
    }
    return bytes;
}

/** Encode a DICT integer operand using a stable byte width. */
function dictNumber(n) {
    if (Number.isInteger(n) && n >= -32768 && n <= 32767) {
        return [28, (n >> 8) & 0xff, n & 0xff];
    }
    return [29, (n >>> 24) & 0xff, (n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff];
}

function dictOp(op) {
    return op >= 1200 ? [12, op - 1200] : [op];
}

function dictEntry(operands, op) {
    const out = [];
    for (let i = 0; i < operands.length; i += 1) {
        const enc = dictNumber(operands[i]);
        for (let j = 0; j < enc.length; j += 1) {
            out.push(enc[j]);
        }
    }
    const opBytes = dictOp(op);
    for (let i = 0; i < opBytes.length; i += 1) {
        out.push(opBytes[i]);
    }
    return out;
}

/**
 * Assemble a complete CFF1 table.
 *
 * `cfg.topDictEntries(offsets)` returns the encoded Top DICT, where `offsets` holds
 * the absolute offsets of the optional tables (charset, encoding, charStrings,
 * private, fdPrivate, fdArray, fdSelect).
 */
function buildCFF1(cfg) {
    if (!cfg.topDictEntries) {
        cfg = Object.assign({}, cfg, {
            topDictEntries: (off) => [...dictEntry([off.charStrings], 17), ...dictEntry([0, 0], 18)]
        });
    }
    const header = [1, 0, 4, 2];
    const nameIndex = makeIndex(cfg.names || [[65]], 1);
    const stringIndex = makeIndex(cfg.strings || [], 1);
    const gsubrsIndex = makeIndex(cfg.gsubrs || [], 1);
    const charsetBytes = cfg.charsetBytes || [];
    const encodingBytes = cfg.encodingBytes || [];
    const charStringsIndex = makeIndex(cfg.charStrings || [[]], 1);
    const subrsIndex = cfg.subrs ? makeIndex(cfg.subrs, 1) : [];
    let privateBytes = [];
    if (cfg.privateEntries) {
        // The Subrs offset is stored relative to the start of the Private DICT,
        // and the Subrs INDEX is placed directly behind it.
        privateBytes = cfg.privateEntries(0);
        const len = privateBytes.length;
        privateBytes = cfg.privateEntries(len);
        if (privateBytes.length !== len) {
            throw new Error('unstable Private DICT length');
        }
    }
    const placeholder = cfg.topDictEntries({
        charStrings: 0, private: 0, charset: 0, encoding: 0, fdArray: 0, fdSelect: 0
    });
    const topDictIndexLen = makeIndex([placeholder], 1).length;
    let offset = 4 + nameIndex.length + topDictIndexLen + stringIndex.length + gsubrsIndex.length;
    const offsets = {};
    offsets.charset = offset;
    offset += charsetBytes.length;
    offsets.encoding = offset;
    offset += encodingBytes.length;
    offsets.charStrings = offset;
    offset += charStringsIndex.length;
    offsets.private = offset;
    offset += privateBytes.length;
    offset += subrsIndex.length;
    offsets.fdPrivate = offset;
    const fdPrivateBytes = cfg.fdPrivateBytes || [];
    offset += fdPrivateBytes.length;
    const fdArrayObjects = cfg.fdArrayObjects ? cfg.fdArrayObjects(offsets.fdPrivate) : [];
    const fdArrayIndex = makeIndex(fdArrayObjects, 1);
    offsets.fdArray = offset;
    offset += fdArrayIndex.length;
    const fdSelectBytes = cfg.fdSelectBytes || [];
    offsets.fdSelect = offset;
    const topDictBytes = cfg.topDictEntries(offsets);
    if (topDictBytes.length !== placeholder.length) {
        throw new Error('unstable Top DICT length');
    }
    const topDictIndex = makeIndex([topDictBytes], 1);
    return new Uint8Array([
        ...header,
        ...nameIndex,
        ...topDictIndex,
        ...stringIndex,
        ...gsubrsIndex,
        ...charsetBytes,
        ...encodingBytes,
        ...charStringsIndex,
        ...privateBytes,
        ...subrsIndex,
        ...fdPrivateBytes,
        ...fdArrayIndex,
        ...fdSelectBytes
    ]);
}

/** Assemble a complete CFF2 table. */
function buildCFF2(cfg) {
    if (!cfg.topDictEntries) {
        cfg = Object.assign({}, cfg, {
            topDictEntries: (off) => dictEntry([off.charStrings], 17)
        });
    }
    const gsubrsIndex = makeIndex(cfg.gsubrs || [], 2);
    const fdPrivateBytes = cfg.fdPrivateBytes || [];
    const fdSelectBytes = cfg.fdSelectBytes || [];
    const charStringsIndex = makeIndex(cfg.charStrings || [[]], 2);
    const placeholder = cfg.topDictEntries({charStrings: 0, fdArray: 0, fdSelect: 0, vstore: 0});
    const topDictLen = placeholder.length;
    let offset = 5 + topDictLen + gsubrsIndex.length;
    const offsets = {};
    offsets.fdPrivate = offset;
    offset += fdPrivateBytes.length;
    const fdArrayObjects = cfg.fdArrayObjects ? cfg.fdArrayObjects(offsets.fdPrivate) : [];
    const fdArrayIndex = makeIndex(fdArrayObjects, 2);
    offsets.fdArray = offset;
    offset += fdArrayIndex.length;
    offsets.fdSelect = offset;
    offset += fdSelectBytes.length;
    offsets.charStrings = offset;
    offset += charStringsIndex.length;
    offsets.vstore = offset;
    const topDictBytes = cfg.topDictEntries(offsets);
    if (topDictBytes.length !== topDictLen) {
        throw new Error('unstable CFF2 Top DICT length');
    }
    const header = [2, 0, 5, (topDictLen >> 8) & 0xff, topDictLen & 0xff];
    return new Uint8Array([
        ...header,
        ...topDictBytes,
        ...gsubrsIndex,
        ...fdPrivateBytes,
        ...fdArrayIndex,
        ...fdSelectBytes,
        ...charStringsIndex
    ]);
}

/** Wrap fixture bytes into a DataView, optionally preceded by `prefixLength` padding bytes. */
function toDataView(bytes, prefixLength = 0) {
    const buf = new Uint8Array(prefixLength + bytes.length);
    buf.set(bytes, prefixLength);
    return new DataView(buf.buffer);
}

/** Run the production parser against fixture bytes and return the (mutated) font. */
function parseBytes(bytes, start = 0, font = {tables: {}}, opt = {}) {
    cff.parse(toDataView(bytes, start), start, font, opt);
    return font;
}

function makeFont(tables = {}) {
    return {tables: tables};
}

// Charstring: rmoveto 0,0 / rlineto 100,0 / endchar  ->  path "M0,0 L100,0 Z"
const RECT_CHARSTRING = [139, 139, 21, 239, 139, 5, 14];
const EMPTY_CHARSTRING = [14];

// ---------------------------------------------------------------------------
// Fixture: a CFF1 table created with cff.make()
// ---------------------------------------------------------------------------

const UPEM = 1000;
let madeCFF1Bytes;
let madeFontOptions;

function buildMadeGlyphs() {
    const notdef = new Glyph({name: '.notdef', advanceWidth: 600});
    notdef.path = new Path();

    const a = new Glyph({name: 'A', advanceWidth: 500});
    a.path = new Path();
    a.path.moveTo(10, 10);
    a.path.lineTo(110, 10);
    a.path.lineTo(110, 110);
    a.path.close();

    const b = new Glyph({name: 'B', advanceWidth: 450});
    b.path = new Path();
    b.path.moveTo(0, 0);
    b.path.quadTo(50, 100, 100, 0);
    b.path.close();

    const glyphs = [notdef, a, b];
    return {
        length: glyphs.length,
        get(i) {
            return glyphs[i];
        }
    };
}

beforeAll(() => {
    madeFontOptions = {
        unitsPerEm: UPEM,
        version: '1.0',
        fullName: 'Test Font',
        familyName: 'Test',
        weightName: 'Regular',
        postScriptName: 'TestFont'
    };
    madeCFF1Bytes = new Uint8Array(cff.make(buildMadeGlyphs(), madeFontOptions).encode());
});

function loadMadeCFF1(font = makeFont(), start = 0) {
    return parseBytes(madeCFF1Bytes, start, font);
}

// ---------------------------------------------------------------------------
// CFF1 happy path
// ---------------------------------------------------------------------------

describe('parseCFFTable - CFF1 table', () => {
    test('registers the parsed table under font.tables.cff', () => {
        const font = loadMadeCFF1();
        expect(font.tables.cff).toBeDefined();
        expect(font.tables.cff2).toBeUndefined();
        expect(typeof font.tables.cff.topDict).toBe('object');
        expect(font.tables.cff.topDict).not.toBeNull();
    });

    test('preserves other entries already present in font.tables', () => {
        const font = loadMadeCFF1({tables: {head: {unitsPerEm: UPEM}}});
        expect(font.tables.head).toEqual({unitsPerEm: UPEM});
        expect(font.tables.cff).toBeDefined();
    });

    test('reads the Top DICT metadata', () => {
        const {topDict} = loadMadeCFF1().tables.cff;
        expect(topDict.version).toBe('1.0');
        expect(topDict.fullName).toBe('Test Font');
        expect(topDict.familyName).toBe('Test');
        expect(topDict.weight).toBe('Regular');
        expect(topDict.isFixedPitch).toBe(0);
        expect(topDict.italicAngle).toBe(0);
        expect(topDict.underlinePosition).toBe(-100);
        expect(topDict.underlineThickness).toBe(50);
        expect(topDict.charstringType).toBe(2);
        expect(topDict.fontMatrix).toHaveLength(6);
        expect(topDict.fontMatrix[0]).toBeCloseTo(1 / UPEM, 10);
        expect(topDict.fontMatrix[3]).toBeCloseTo(1 / UPEM, 10);
        expect(topDict.fontMatrix[1]).toBe(0);
        expect(topDict.fontMatrix[4]).toBe(0);
        expect(typeof topDict.charStrings).toBe('number');
        expect(topDict.charStrings).toBeGreaterThan(0);
    });

    test('derives the glyph count and builds a loadable glyph set', () => {
        const font = loadMadeCFF1();
        expect(font.nGlyphs).toBe(3);
        expect(font.glyphs).toBeDefined();
        expect(font.glyphs.length).toBe(3);

        expect(font.glyphs.get(0).path.commands).toEqual([]);
        expect(font.glyphs.get(1).path.commands).toEqual([
            {type: 'M', x: 10, y: 10},
            {type: 'L', x: 110, y: 10},
            {type: 'L', x: 110, y: 110},
            {type: 'Z'}
        ]);
        // A quadratic curve is converted to a cubic bezier by the charstring parser.
        expect(font.glyphs.get(2).path.commands).toEqual([
            {type: 'M', x: 0, y: 0},
            {type: 'C', x1: 33, y1: 67, x2: 67, y2: 67, x: 100, y: 0},
            {type: 'Z'}
        ]);
    });

    test('leaves CID and subroutine state at their defaults', () => {
        const font = loadMadeCFF1();
        expect(font.isCIDFont).toBeUndefined();
        expect(font.gsubrs).toEqual([]);
        expect(font.gsubrsBias).toBe(107);
        expect(font.subrs).toEqual([]);
        expect(font.subrsBias).toBe(0);
        expect(font.defaultWidthX).toBe(0);
        expect(font.nominalWidthX).toBe(0);
        expect(font.tables.cff.topDict._subrs).toEqual([]);
        expect(font.tables.cff.topDict._subrsBias).toBe(0);
    });

    test('builds a CFF encoding and installs it as font.encoding', () => {
        const font = loadMadeCFF1();
        expect(font.cffEncoding).toBeInstanceOf(encodingModule.CffEncoding);
        expect(font.cffEncoding.charset).toEqual(['.notdef', 'A', 'B']);
        expect(font.cffEncoding.encoding).toBe(encodingModule.cffStandardEncoding);
        expect(font.encoding).toBe(font.cffEncoding);
    });

