const UPEM = 1000;
let madeCFF1Bytes;
let madeFontOptions;

function buildMadeGlyphs() {
    const notdef = new Glyph({name: '.notdef', advanceWidth: 600});
    notdef.path = new Path();

    const a = new Glyph({name: 'A', advanceWidth: 500});
    a.path = new Path();
    a.path.moveTo(10, 10);
    a.path.lineTo(110, 10);
    a.path.lineTo(110, 110);
    a.path.close();

    const b = new Glyph({name: 'B', advanceWidth: 450});
    b.path = new Path();
    b.path.moveTo(0, 0);
    b.path.quadTo(50, 100, 100, 0);
    b.path.close();

    const glyphs = [notdef, a, b];
    return {
        length: glyphs.length,
        get(i) {
            return glyphs[i];
        }
    };
}

beforeAll(() => {
    madeFontOptions = {
        unitsPerEm: UPEM,
        version: '1.0',
        fullName: 'Test Font',
        familyName: 'Test',
        weightName: 'Regular',
        postScriptName: 'TestFont'
    };
    madeCFF1Bytes = new Uint8Array(cff.make(buildMadeGlyphs(), madeFontOptions).encode());
});

function loadMadeCFF1(font = makeFont(), start = 0) {
    return parseBytes(madeCFF1Bytes, start, font);
}

