let realCFF2Fixture;

/**
 * Extract the CFF2 table of the bundled variable test font together with its maxp
 * glyph count, so that `parseCFFTable` can be called directly.
 */
async function loadRealCFF2Fixture() {
    if (realCFF2Fixture) {
        return realCFF2Fixture;
    }
    const file = pathModule.join(__dirname, '..', '..', 'fonts', 'TestRVRN-CFF2.otf');
    const buf = fs.readFileSync(file);
    const arrayBuffer = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
    const view = new DataView(arrayBuffer);
    const numTables = view.getUint16(4);
    const tables = {};
    for (let i = 0; i < numTables; i += 1) {
        const record = 12 + i * 16;
        let tag = '';
        for (let j = 0; j < 4; j += 1) {
            tag += String.fromCharCode(view.getUint8(record + j));
        }
        tables[tag] = {offset: view.getUint32(record + 8), length: view.getUint32(record + 12)};
    }
    const numGlyphs = view.getUint16(tables.maxp.offset + 4);
    realCFF2Fixture = {
        view: view,
        offset: tables.CFF2.offset,
        numGlyphs: numGlyphs
    };
    return realCFF2Fixture;
}

