    test('does not compare glyph counts when maxp is absent', async () => {
        const fixture = await loadRealCFF2Fixture();
        const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
        try {
            const font = {numGlyphs: fixture.numGlyphs, tables: {}};
            cff.parse(fixture.view, fixture.offset, font, {});
            expect(font.nGlyphs).toBe(fixture.numGlyphs);
            expect(errorSpy).not.toHaveBeenCalled();
        } finally {
            errorSpy.mockRestore();
        }
    });

    test('parses a hand built CFF2 table with FDArray and FDSelect', () => {
        const fdPrivateEntries = [...dictEntry([50], 20), ...dictEntry([5], 21)];
        const bytes = buildCFF2({
            charStrings: [[139, 139, 21], [139, 139, 21]],
            fdPrivateBytes: fdPrivateEntries,
            fdArrayObjects: (fdPrivateOffset) => [
                [...dictEntry([fdPrivateEntries.length, fdPrivateOffset], 18)]
            ],
            fdSelectBytes: [0, 0, 0],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([off.fdArray], 1236),
                ...dictEntry([off.fdSelect], 1237)
            ]
        });

        const font = {numGlyphs: 2, tables: {}};
        parseBytes(bytes, 0, font);

        expect(font.tables.cff2).toBeDefined();
        expect(font.tables.cff).toBeUndefined();
        expect(font.nGlyphs).toBe(2);
        expect(font.glyphs.length).toBe(2);
        expect(font.tables.cff2.topDict._fdArray).toHaveLength(1);
        expect(font.tables.cff2.topDict._fdArray[0]._privateDict).toBeDefined();
        expect(font.tables.cff2.topDict._fdSelect).toEqual([0, 0]);
    });

    test('throws when a CFF2 table has no FDArray', () => {
        const bytes = buildCFF2({
            charStrings: [[139, 139, 21]],
            topDictEntries: (off) => dictEntry([off.charStrings], 17)
        });
        expect(() => parseBytes(bytes, 0, {numGlyphs: 1, tables: {}}))
            .toThrow('This is a CFF2 font, but FDArray information is missing');
    });
});

