function buildSimpleCFF1(overrides = {}) {
    return buildCFF1(Object.assign({
        charStrings: [EMPTY_CHARSTRING, EMPTY_CHARSTRING],
        topDictEntries: (off) => [
            ...dictEntry([off.charStrings], 17),
            ...dictEntry([0, 0], 18),
            ...dictEntry([(overrides.charset !== undefined ? overrides.charset : 0)], 15),
            ...dictEntry([(overrides.encoding !== undefined ? overrides.encoding : 0)], 16)
        ]
    }, overrides));
}

