        expect(font.cffEncoding.charset).toBe(encodingModule.cffISOAdobeStrings);
        expect(font.cffEncoding.encoding).toBe(encodingModule.cffStandardEncoding);
    });

    test('charset 1 selects the Expert charset', () => {
        const font = parseBytes(buildSimpleCFF1({charset: 1}));
        expect(font.cffEncoding.charset).toBe(encodingModule.cffIExpertStrings);
    });

    test('charset 2 selects the ExpertSubset charset', () => {
        const font = parseBytes(buildSimpleCFF1({charset: 2}));
        expect(font.cffEncoding.charset).toBe(encodingModule.cffExpertSubsetStrings);
    });
});

