// ---------------------------------------------------------------------------
// CFF2 tables
// ---------------------------------------------------------------------------

let realCFF2Fixture;

/**
 * Extract the CFF2 table of the bundled variable test font together with its maxp
 * glyph count, so that `parseCFFTable` can be called directly.
 */
async function loadRealCFF2Fixture() {
    if (realCFF2Fixture) {
        return realCFF2Fixture;
    }
    const file = pathModule.join(__dirname, '..', '..', 'fonts', 'TestRVRN-CFF2.otf');
    const buf = fs.readFileSync(file);
    const arrayBuffer = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
    const view = new DataView(arrayBuffer);
    const numTables = view.getUint16(4);
    const tables = {};
    for (let i = 0; i < numTables; i += 1) {
        const record = 12 + i * 16;
        let tag = '';
        for (let j = 0; j < 4; j += 1) {
            tag += String.fromCharCode(view.getUint8(record + j));
        }
        tables[tag] = {offset: view.getUint32(record + 8), length: view.getUint32(record + 12)};
    }
    const numGlyphs = view.getUint16(tables.maxp.offset + 4);
    realCFF2Fixture = {
        view: view,
        offset: tables.CFF2.offset,
        numGlyphs: numGlyphs
    };
    return realCFF2Fixture;
}

describe('parseCFFTable - CFF2 table', () => {
    test('registers the parsed table under font.tables.cff2', async () => {
        const fixture = await loadRealCFF2Fixture();
        const font = {numGlyphs: fixture.numGlyphs, tables: {maxp: {numGlyphs: fixture.numGlyphs}}};
        cff.parse(fixture.view, fixture.offset, font, {});

        expect(font.tables.cff2).toBeDefined();
        expect(font.tables.cff).toBeUndefined();
        expect(font.tables.cff2.topDict).toBeDefined();
        expect(font.nGlyphs).toBe(fixture.numGlyphs);
        expect(font.glyphs.length).toBe(fixture.numGlyphs);
    });

    test('parses the FDArray, its Private DICT and the variation store', async () => {
        const fixture = await loadRealCFF2Fixture();
        const font = {numGlyphs: fixture.numGlyphs, tables: {maxp: {numGlyphs: fixture.numGlyphs}}};
        cff.parse(fixture.view, fixture.offset, font, {});

        const topDict = font.tables.cff2.topDict;
        expect(typeof topDict.charStrings).toBe('number');
        expect(topDict.charStrings).toBeGreaterThan(0);
        expect(typeof topDict.fdArray).toBe('number');
        expect(topDict.fdSelect).toBeNull();
        expect(topDict._fdArray).toHaveLength(1);
        expect(topDict._fdSelect).toBeUndefined();
        expect(topDict._fdArray[0]._privateDict).toBeDefined();
        expect(topDict._fdArray[0]._privateDict.vsindex).toBe(0);
        expect(topDict._fdArray[0]._subrs.length).toBe(27);
        expect(topDict._fdArray[0]._subrsBias).toBe(107);
        expect(topDict._vstore).toBeDefined();
        expect(topDict._vstore.itemVariationStore.format).toBe(1);
        expect(topDict._vstore.itemVariationStore.variationRegions.length).toBeGreaterThan(0);
        expect(font.gsubrs).toEqual([]);
        expect(font.gsubrsBias).toBe(107);
    });

    test('loads CFF2 glyph outlines lazily', async () => {
        const fixture = await loadRealCFF2Fixture();
        const font = {numGlyphs: fixture.numGlyphs, tables: {maxp: {numGlyphs: fixture.numGlyphs}}};
        cff.parse(fixture.view, fixture.offset, font, {});

        expect(font.glyphs.get(0).path.commands).toEqual([]);
        const commands = font.glyphs.get(1).path.commands;
        expect(commands.length).toBeGreaterThan(0);
        expect(commands[0]).toEqual({type: 'M', x: 200, y: 700});
        expect(commands.some((c) => c.type === 'L')).toBe(true);
    });

    test('reports a glyph count mismatch with maxp through console.error', async () => {
        const fixture = await loadRealCFF2Fixture();
        const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
        try {
            const wrongCount = fixture.numGlyphs - 1;
            const font = {numGlyphs: wrongCount, tables: {maxp: {numGlyphs: wrongCount}}};
            cff.parse(fixture.view, fixture.offset, font, {});
            expect(font.nGlyphs).toBe(fixture.numGlyphs);
            expect(errorSpy).toHaveBeenCalledTimes(1);
            expect(errorSpy.mock.calls[0][0]).toBe(
                `Glyph count in the CFF2 table (${fixture.numGlyphs}) must correspond to the glyph count in the maxp table (${wrongCount})`
            );
        } finally {
            errorSpy.mockRestore();
        }
    });

    test('does not compare glyph counts when maxp is absent', async () => {
        const fixture = await loadRealCFF2Fixture();
        const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
        try {
            const font = {numGlyphs: fixture.numGlyphs, tables: {}};
            cff.parse(fixture.view, fixture.offset, font, {});
            expect(font.nGlyphs).toBe(fixture.numGlyphs);
            expect(errorSpy).not.toHaveBeenCalled();
        } finally {
            errorSpy.mockRestore();
        }
    });

    test('parses a hand built CFF2 table with FDArray and FDSelect', () => {
        const fdPrivateEntries = [...dictEntry([50], 20), ...dictEntry([5], 21)];
        const bytes = buildCFF2({
            charStrings: [[139, 139, 21], [139, 139, 21]],
            fdPrivateBytes: fdPrivateEntries,
            fdArrayObjects: (fdPrivateOffset) => [
                [...dictEntry([fdPrivateEntries.length, fdPrivateOffset], 18)]
            ],
            fdSelectBytes: [0, 0, 0],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([off.fdArray], 1236),
                ...dictEntry([off.fdSelect], 1237)
            ]
        });

        const font = {numGlyphs: 2, tables: {}};
        parseBytes(bytes, 0, font);

        expect(font.tables.cff2).toBeDefined();
        expect(font.tables.cff).toBeUndefined();
        expect(font.nGlyphs).toBe(2);
        expect(font.glyphs.length).toBe(2);
        expect(font.tables.cff2.topDict._fdArray).toHaveLength(1);
        expect(font.tables.cff2.topDict._fdArray[0]._privateDict).toBeDefined();
        expect(font.tables.cff2.topDict._fdSelect).toEqual([0, 0]);
    });

    test('throws when a CFF2 table has no FDArray', () => {
        const bytes = buildCFF2({
            charStrings: [[139, 139, 21]],
            topDictEntries: (off) => dictEntry([off.charStrings], 17)
        });
        expect(() => parseBytes(bytes, 0, {numGlyphs: 1, tables: {}}))
            .toThrow('This is a CFF2 font, but FDArray information is missing');
    });
});

