describe('parseCFFTable - invalid input', () => {
    test('rejects unsupported CFF major versions', () => {
        const data = toDataView(new Uint8Array([3, 0, 4, 2, 0, 0, 0, 0]));
        const font = {tables: {}};
        expect(() => cff.parse(data, 0, font, {})).toThrow('Unsupported CFF table version 3.0');
        expect(font.tables.cff).toBeUndefined();
        expect(font.tables.cff2).toBeUndefined();
    });

    test('rejects a FontSet containing more than one font', () => {
        const bytes = new Uint8Array([
            ...[1, 0, 4, 2],
            ...makeIndex([[65]], 1),
            ...makeIndex([[], []], 1),
            ...makeIndex([], 1),
            ...makeIndex([], 1)
        ]);
        expect(() => parseBytes(bytes)).toThrow(
            "CFF table has too many fonts in 'FontSet' - count of fonts NameIndex.length = 2"
        );
    });

    test('rejects a CID font without FDArray/FDSelect references', () => {
        const bytes = buildCFF1({
            charStrings: [[14]],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([0, 0], 18),
                ...dictEntry([1, 2, 0], 1230),
                ...dictEntry([0], 1236),
                ...dictEntry([0], 1237)
            ]
        });
        expect(() => parseBytes(bytes, 0, {numGlyphs: 1, tables: {}})).toThrow(
            'Font is marked as a CID font, but FDArray and/or FDSelect information is missing'
        );
    });
});

