// Charsets and encodings
// ---------------------------------------------------------------------------

function buildSimpleCFF1(overrides = {}) {
    return buildCFF1(Object.assign({
        charStrings: [EMPTY_CHARSTRING, EMPTY_CHARSTRING],
        topDictEntries: (off) => [
            ...dictEntry([off.charStrings], 17),
            ...dictEntry([0, 0], 18),
            ...dictEntry([(overrides.charset !== undefined ? overrides.charset : 0)], 15),
            ...dictEntry([(overrides.encoding !== undefined ? overrides.encoding : 0)], 16)
        ]
    }, overrides));
}

describe('parseCFFTable - predefined charsets', () => {
    test('charset 0 selects the ISOAdobe charset', () => {
        const font = parseBytes(buildSimpleCFF1({charset: 0}));
        expect(font.cffEncoding.charset).toBe(encodingModule.cffISOAdobeStrings);
        expect(font.cffEncoding.encoding).toBe(encodingModule.cffStandardEncoding);
    });

    test('charset 1 selects the Expert charset', () => {
        const font = parseBytes(buildSimpleCFF1({charset: 1}));
        expect(font.cffEncoding.charset).toBe(encodingModule.cffIExpertStrings);
    });

    test('charset 2 selects the ExpertSubset charset', () => {
        const font = parseBytes(buildSimpleCFF1({charset: 2}));
        expect(font.cffEncoding.charset).toBe(encodingModule.cffExpertSubsetStrings);
    });
});

describe('parseCFFTable - custom charset', () => {
    test('reads charset format 0 and resolves SIDs against the string INDEX', () => {
        const font = parseBytes(buildCFF1({
            strings: [[99, 117, 115, 116]], // "cust"
            charsetBytes: [0, 0x01, 0x87], // format 0, SID 391 -> first custom string
            charStrings: [EMPTY_CHARSTRING, EMPTY_CHARSTRING],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([0, 0], 18),
                ...dictEntry([off.charset], 15),
                ...dictEntry([0], 16)
            ]
        }));

        expect(font.nGlyphs).toBe(2);
        expect(font.cffEncoding.charset).toEqual(['.notdef', 'cust']);
        expect(font.cffEncoding.charToGlyphIndex('cust')).toBe(1);
    });

    test('rejects an unknown charset format', () => {
        const bytes = buildCFF1({
            charsetBytes: [3],
            charStrings: [EMPTY_CHARSTRING, EMPTY_CHARSTRING],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([0, 0], 18),
                ...dictEntry([off.charset], 15)
            ]
        });
        expect(() => parseBytes(bytes)).toThrow('Unknown charset format 3');
    });
});

describe('parseCFFTable - encodings', () => {
    test('encoding 0 selects the Standard encoding', () => {
        const font = parseBytes(buildSimpleCFF1({encoding: 0}));
        expect(font.cffEncoding.encoding).toBe(encodingModule.cffStandardEncoding);
    });

    test('encoding 1 selects the Expert encoding', () => {
        const font = parseBytes(buildSimpleCFF1({encoding: 1}));
        expect(font.cffEncoding.encoding).toBe(encodingModule.cffExpertEncoding);
    });

    test('reads a custom encoding in format 0', () => {
        const font = parseBytes(buildCFF1({
            encodingBytes: [0, 1, 65], // format 0, one code: 65
            charStrings: [EMPTY_CHARSTRING],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([0, 0], 18),
                ...dictEntry([0], 15),
                ...dictEntry([off.encoding], 16)
            ]
        }));
        expect(font.cffEncoding.encoding).toEqual({65: 0});
    });

    test('reads a custom encoding in format 1', () => {
        const font = parseBytes(buildCFF1({
            encodingBytes: [1, 1, 65, 1], // format 1, one range starting at code 65, 1 extra code
            charStrings: [EMPTY_CHARSTRING],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([0, 0], 18),
                ...dictEntry([0], 15),
                ...dictEntry([off.encoding], 16)
            ]
        }));
        expect(font.cffEncoding.encoding).toEqual({65: 1, 66: 2});
    });

    test('rejects an unknown encoding format', () => {
        const bytes = buildCFF1({
            encodingBytes: [9],
            charStrings: [EMPTY_CHARSTRING],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([0, 0], 18),
                ...dictEntry([off.encoding], 16)
            ]
        });
        expect(() => parseBytes(bytes)).toThrow('Unknown encoding format 9');
    });
});

