// Private DICT and subroutines
// ---------------------------------------------------------------------------

describe('parseCFFTable - Private DICT', () => {
    test('reads defaultWidthX/nominalWidthX and local subroutines from the Private DICT', () => {
        const privateEntries = (subrsOffset) => [
            ...dictEntry([100], 20),
            ...dictEntry([20], 21),
            ...dictEntry([subrsOffset], 19)
        ];
        const bytes = buildCFF1({
            charStrings: [EMPTY_CHARSTRING],
            privateEntries: privateEntries,
            subrs: [RECT_CHARSTRING],
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([privateEntries(0).length, off.private], 18)
            ]
        });

        const font = parseBytes(bytes);

        expect(font.defaultWidthX).toBe(100);
        expect(font.nominalWidthX).toBe(20);
        expect(font.subrs).toHaveLength(1);
        expect(font.subrsBias).toBe(107);
        expect(font.tables.cff.topDict._privateDict).toBeDefined();
        expect(font.tables.cff.topDict._privateDict.defaultWidthX).toBe(100);
        expect(font.tables.cff.topDict._privateDict.nominalWidthX).toBe(20);
        expect(font.tables.cff.topDict._defaultWidthX).toBe(100);
        expect(font.tables.cff.topDict._nominalWidthX).toBe(20);
        expect(font.tables.cff.topDict._subrs).toHaveLength(1);
    });

    test('keeps empty subroutine lists when no Subrs offset is present', () => {
        const privateEntries = () => [...dictEntry([300], 20), ...dictEntry([7], 21)];
        const bytes = buildCFF1({
            charStrings: [EMPTY_CHARSTRING],
            privateEntries: privateEntries,
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([privateEntries(0).length, off.private], 18)
            ]
        });

        const font = parseBytes(bytes);

        expect(font.defaultWidthX).toBe(300);
        expect(font.nominalWidthX).toBe(7);
        expect(font.subrs).toEqual([]);
        expect(font.subrsBias).toBe(0);
    });

    test.each([
        [1239, 107],
        [1240, 1131]
    ])('computes the local subr bias from %i subroutines (%i)', (count, expectedBias) => {
        const subrs = new Array(count).fill(EMPTY_CHARSTRING);
        const privateEntries = (subrsOffset) => dictEntry([subrsOffset], 19);
        const bytes = buildCFF1({
            charStrings: [EMPTY_CHARSTRING],
            privateEntries: privateEntries,
            subrs: subrs,
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([privateEntries(0).length, off.private], 18)
            ]
        });
        const font = parseBytes(bytes);
        expect(font.subrs).toHaveLength(count);
        expect(font.subrsBias).toBe(expectedBias);
    });

    test.each([
        [1239, 107],
        [1240, 1131]
    ])('computes the global subr bias from %i subroutines (%i)', (count, expectedBias) => {
        const gsubrs = new Array(count).fill(EMPTY_CHARSTRING);
        const bytes = buildCFF1({
            gsubrs: gsubrs,
            charStrings: [EMPTY_CHARSTRING]
        });
        const font = parseBytes(bytes);
        expect(font.gsubrs).toHaveLength(count);
        expect(font.gsubrsBias).toBe(expectedBias);
        expect(font.tables.cff.topDict._subrs).toEqual([]);
    });
});

