describe('parseCFFTable - CID-keyed CFF1 font', () => {
    function buildCIDFont() {
        const fdPrivateEntries = () => [...dictEntry([50], 20), ...dictEntry([5], 21)];
        return buildCFF1({
            charStrings: [EMPTY_CHARSTRING, RECT_CHARSTRING],
            charsetBytes: [0, 0x00, 0x01], // format 0, SID 1 for the second glyph
            fdPrivateBytes: fdPrivateEntries(),
            fdArrayObjects: (fdPrivateOffset) => [
                [...dictEntry([fdPrivateEntries().length, fdPrivateOffset], 18)]
            ],
            fdSelectBytes: [0, 0, 0], // format 0, two glyphs mapped to FD 0
            topDictEntries: (off) => [
                ...dictEntry([off.charStrings], 17),
                ...dictEntry([0, 0], 18),
                ...dictEntry([off.charset], 15),
                ...dictEntry([0], 16),
                ...dictEntry([1, 2, 0], 1230), // ROS
                ...dictEntry([off.fdArray], 1236),
                ...dictEntry([off.fdSelect], 1237)
            ]
        });
    }

    test('marks the font as CID and records the ROS values', () => {
        const font = parseBytes(buildCIDFont(), 0, {numGlyphs: 2, tables: {}});
        expect(font.isCIDFont).toBe(true);
        expect(font.tables.cff.topDict.ros).toEqual([
            encodingModule.cffStandardStrings[1],
            encodingModule.cffStandardStrings[2],
            0
        ]);
        expect(font.nGlyphs).toBe(2);
    });

    test('parses the FDArray with its Private DICT and the FDSelect array', () => {
        const font = parseBytes(buildCIDFont(), 0, {numGlyphs: 2, tables: {}});
        const topDict = font.tables.cff.topDict;
        expect(topDict._fdArray).toHaveLength(1);
        expect(topDict._fdArray[0]._privateDict).toBeDefined();
        expect(topDict._fdArray[0]._privateDict.defaultWidthX).toBe(50);
        expect(topDict._fdArray[0]._privateDict.nominalWidthX).toBe(5);
        expect(topDict._fdArray[0]._subrs).toEqual([]);
        expect(topDict._fdArray[0]._subrsBias).toBe(0);
        expect(topDict._fdSelect).toEqual([0, 0]);
    });

    test('keeps numeric SIDs in the charset and resolves glyph outlines through the FDArray', () => {
        const font = parseBytes(buildCIDFont(), 0, {numGlyphs: 2, tables: {}});
        expect(font.cffEncoding.charset).toEqual(['.notdef', 1]);
        expect(font.glyphs.get(1).path.commands).toEqual([
            {type: 'M', x: 0, y: 0},
            {type: 'L', x: 100, y: 0},
            {type: 'Z'}
        ]);
    });
});
