// Unit tests for makeCmapTable() from src/tables/cmap.mjs.
//
// The implementation lives in an ES module, so it is pulled in through a dynamic
// import inside beforeAll(). That keeps this file usable both in a CommonJS Jest
// environment and in a native-ESM Jest environment.

let makeCmapTable;
let Table;

beforeAll(async () => {
    ({ makeCmapTable } = await import('../../../src/tables/cmap.mjs'));
    ({ default: Table } = await import('../../../src/table.mjs'));
});

// Number of Format 4 segments that still fit into the USHORT `length` field:
// floor((65535 - 14 - 2) / 8) = 8189.
const FORMAT4_SEGMENT_LIMIT = 8189;

function glyph(unicode, unicodes) {
    return { unicode: unicode, unicodes: unicodes || [unicode] };
}

function glyphSet(list) {
    return {
        length: list.length,
        get: function(i) { return list[i]; }
    };
}

// Glyph set whose code points are two apart, so no two segments are adjacent and
// the merged segment count equals `count`.
function evenlySpacedGlyphSet(count) {
    const list = [];
    for (let i = 0; i < count; i += 1) {
        list.push(glyph(i * 2));
    }
    return glyphSet(list);
}

function field(t, name) {
    const matches = t.fields.filter(function(f) { return f.name === name; });
    if (matches.length !== 1) {
        throw new Error('expected exactly one field named "' + name + '", found ' + matches.length);
    }
    return matches[0];
}

function fieldValues(t, prefix) {
    return t.fields
        .filter(function(f) { return f.name.indexOf(prefix) === 0; })
        .map(function(f) { return f.value; });
}

function hasFieldStartingWith(t, prefix) {
    return t.fields.some(function(f) { return f.name.indexOf(prefix) === 0; });
}

