//
// The .notdef glyph intentionally has wild metrics. fontToSfntTable must use
// it for glyph counting / Unicode bookkeeping but exclude it from the global
// metrics tables.
function standardGlyphs() {
    return [
        makeGlyph({
            name: '.notdef',
            advanceWidth: 9999,
            leftSideBearing: 999,
            xMin: -1000,
            yMin: -1000,
            xMax: 1000,
            yMax: 1000
        }),
        makeGlyph({name: '.null', unicode: 0, advanceWidth: 0, leftSideBearing: 0}),
        makeGlyph({
            name: 'A',
            unicode: 65,
            advanceWidth: 600,
            leftSideBearing: 10,
            xMin: 10,
            yMin: 0,
            xMax: 60,
            yMax: 100
