        makeGlyph({
            name: 'x',
            unicode: 120,
            advanceWidth: 400,
            leftSideBearing: 20,
            xMin: 20,
            yMin: 0,
            xMax: 80,
            yMax: 50
        }),
        makeGlyph({
            name: 'space',
            unicode: 32,
            advanceWidth: 250,
            leftSideBearing: 0,
            xMin: 0,
            yMin: 0,
            xMax: 0,
            yMax: 0
        })
    ];
}

function makeFont(overrides = {}) {
    return new Font(Object.assign({
        familyName: 'Test Family',
        styleName: 'Regular',
        unitsPerEm: 1000,
        ascender: 800,
        descender: -200,
        createdTimestamp: 123456789,
        glyphs: standardGlyphs()
    }, overrides));
}

function getTable(sfnt, tableName) {
    const table = sfnt.tables.find((candidate) => candidate.tableName === tableName);
    if (!table) {
