// Tests for src/tables/sfnt.mjs -> fontToSfntTable (exported as fontToTable).
//
// The production modules are ES modules, so they are loaded with dynamic
// import() from this CommonJS Jest test file.

let Font;
let Glyph;
let Path;
let sfntModule;
let nameTableModule;

beforeAll(async () => {
    Font = (await import('../../../src/font.mjs')).default;
    Glyph = (await import('../../../src/glyph.mjs')).default;
    Path = (await import('../../../src/path.mjs')).default;
    sfntModule = (await import('../../../src/tables/sfnt.mjs')).default;
    nameTableModule = (await import('../../../src/tables/name.mjs')).default;
});

const UINT32_MAX = 0xFFFFFFFF;

function makeGlyph({
    name,
    unicode,
    advanceWidth,
    leftSideBearing = 0,
    xMin = 0,
    yMin = 0,
    xMax = 0,
    yMax = 0
} = {}) {
    const path = new Path();
    path.moveTo(xMin, yMin);
    path.lineTo(xMax, yMin);
    path.lineTo(xMax, yMax);
    path.lineTo(xMin, yMax);
    path.close();

    const options = {name, leftSideBearing, path};
    if (advanceWidth !== undefined) {
        options.advanceWidth = advanceWidth;
    }
    if (unicode !== undefined) {
        options.unicode = unicode;
    }

    return new Glyph(options);
}

