let VariationProcessor;

beforeAll(async () => {
    ({ VariationProcessor } = await import('../../src/variationprocessor.mjs'));
});

const WEIGHT_AXIS = { tag: 'wght', minValue: 100, defaultValue: 400, maxValue: 900 };
const WIDTH_AXIS = { tag: 'wdth', minValue: 50, defaultValue: 100, maxValue: 200 };

function createProcessor({ axes = [WEIGHT_AXIS], avar, gvar, coords = {} } = {}) {
    const get = jest.fn(() => coords);
    const font = {
        variation: { get },
        tables: {
            fvar: { axes },
            ...(avar ? { avar } : {}),
            ...(gvar ? { gvar } : {}),
        },
    };
    return { processor: new VariationProcessor(font), get, font };
}

function point(x, y, lastPointOfContour = false, onCurve = true) {
    return { x, y, onCurve, lastPointOfContour };
}

function gvarHeader(overrides = {}) {
    return { peakTuple: [1], privatePoints: [], deltas: [], deltasY: [], ...overrides };
}

function cvarHeader(overrides = {}) {
    return { peakTuple: [1], privatePoints: [], deltas: [], ...overrides };
}

function variationData(headers, sharedPoints = []) {
    return { headers, sharedPoints };
}

describe('VariationProcessor.applyTupleVariationStore', () => {
    describe('gvar flavor', () => {
        test('applies deltas with a factor of 1 at the axis maximum and returns rounded copies', () => {
            const { processor } = createProcessor();
            const points = [point(10.4, 20.4), point(1.2, 2.2, true, false)];
            const headers = [gvarHeader({ deltas: [5.3, -1.2], deltasY: [2.4, 3.6] })];

            const result = processor.applyTupleVariationStore(variationData(headers), points, { wght: 900 });

            expect(result).toEqual([point(16, 23), point(0, 6, true, false)]);
            expect(result).not.toBe(points);
            expect(result[0]).not.toBe(points[0]);
            expect(points).toEqual([point(10.4, 20.4), point(1.2, 2.2, true, false)]);
        });

        test('defaults to the gvar flavor when no flavor is provided', () => {
            const { processor } = createProcessor();
            const headers = [gvarHeader({ deltas: [3], deltasY: [4] })];

            const result = processor.applyTupleVariationStore(variationData(headers), [point(1, 1)], { wght: 900 });

            expect(result).toEqual([point(4, 5)]);
        });

        test('uses font variation coordinates when coords are not provided', () => {
            const { processor, get } = createProcessor({ coords: { wght: 900 } });
            const headers = [gvarHeader({ deltas: [4], deltasY: [6] })];

            const result = processor.applyTupleVariationStore(variationData(headers), [point(0, 0)]);

            expect(get).toHaveBeenCalledTimes(1);
            expect(result).toEqual([point(4, 6)]);
        });

        test('uses the provided coords instead of the font variation coordinates', () => {
